"""
SLLIP V3 Automated Chunking & Token Truncation Test Suite
=========================================================
Verifies that generated SAC chunks never exceed the 256-token limit of all-MiniLM-L6-v2,
and ensures that both compact summary and chunk body are preserved.
"""

from chunking_engine import TokenAwareSACChunker, MAX_ALLOWED_TOKENS


def test_sac_chunks_within_token_limit():
    """Verify that chunks generated by TokenAwareSACChunker stay strictly within limits."""
    chunker = TokenAwareSACChunker()

    sample_judgment = (
        "In the Court of Appeal of Sri Lanka. Case No. CA/1054/98. "
        "The Appellant filed an appeal against the decree of the District Court of Galle "
        "dismissing the action for dissolution of marriage and permanent alimony. "
        "The Appellant urged that the respondent had subjected her to persistent cruelty, "
        "verbal abuse, and constructive desertion, culminating in her ejection from the "
        "matrimonial domicile in January 1996. The learned trial judge erroneously concluded "
        "that the appellant's testimony lacked corroboration. Under Section 602 of the Civil "
        "Procedure Code, corroboration in matrimonial disputes is not a rigid statutory mandate. "
        "The respondent failed to provide monthly maintenance for the minor children as required "
        "by the Maintenance Act No. 37 of 1999."
    )

    chunks = chunker.process_document("TEST_DOC_001", sample_judgment, {"verdict": "Appeal Allowed"})
    assert len(chunks) > 0, "No chunks were generated."

    for c in chunks:
        assert c["token_count"] <= MAX_ALLOWED_TOKENS, f"Chunk {c['chunk_id']} exceeded token limit: {c['token_count']}"
        assert "[CASE CONTEXT]:" in c["augmented_text"]
        assert "[FACTS]:" in c["augmented_text"]
        assert len(c["global_summary"]) > 0
        assert len(c["raw_chunk_text"]) > 0
